import rawTable from '../../../resources/data/versions.json'
import { VersionTableSchema, type VersionTable } from '../model/versions'

/**
 * The bundled version table (resources/data/versions.json, generated by scripts/update-versions.mjs).
 * Imported statically so electron-vite bundles it into main and the renderer; validated once at load.
 */
export const versionTable: VersionTable = VersionTableSchema.parse(rawTable)
